	('2693934a-86dd-45df-8b2a-ca3bbfbb6152', 'croissants', 'Croissants & Pastries', 'ครัวซองและเพสทรี้', 'Buttery, flaky layers made with love and traditional techniques.', 'ชั้นเนยกรอบนอกนุ่มในทำด้วยใจรักและเทคนิคแบบดั้งเดิม', 1, true, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '可颂与酥点', '传统工艺，层层酥香，满满黄油香气。'),
	('09733918-c224-40fc-9978-9bbd060f770c', 'breads', 'Breads', 'ขนมปัง', 'Artisan breads baked fresh with premium ingredients.', 'ขนมปังช่างฝีมืออบสดใหม่ด้วยวัตถุดิบคุณภาพเยี่ยม', 2, true, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '面包', '优质原料，新鲜出炉的手工面包。'),
	('f424b263-5e52-4c87-bac0-c6f32e91e773', 'cakes', 'Cakes & Cookies', 'เค้กและคุกกี้', 'Sweet treats perfect for any celebration or afternoon delight.', 'ขนมหวานสุดอร่อยเพื่อการเฉลิมฉลองหรือติดตามหลังบ่าย', 3, true, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '蛋糕与饼干', '庆祝时刻或午后茶点的甜蜜选择。'),
	('d5312ef4-391e-406f-a94e-c46d9b85221d', 'quiche', 'Quiche, Pizza & More', 'คีช พิซซ่า และอื่นๆ', 'Savory options including buns, quiche, and artisan pizza.', 'เมนูคร่อมรวมถึงขนมปังชนิดต่างๆ คีช และพิซซ่าช่างฝีมือ', 4, true, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '法式咸派、披萨等', '包括各式面包、法式咸派和手工披萨。');
