INSERT INTO "public"."cms_pages" ("id", "page_key", "title_en", "title_th", "body_en", "body_th", "created_at", "updated_at", "title_zh", "body_zh") VALUES
	('c96b8ef3-f7ce-457f-ac60-086aa412bc0b', 'home_hero', 'Artisan Bakery in Chiang Mai', 'เบเกอรี่ช่างฝีมือในเชียงใหม่', 'Freshly baked goods, made with love. Pre-order for weekend pickup.', 'ขนมปังและเบเกอรี่สดใหม่ ทำด้วยใจรัก สั่งจองล่วงหน้าสำหรับรับของสุดสัปดาห์', '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', NULL, NULL),
	('47fe413b-4c5f-4301-bd9e-22e179dec5ae', 'home_cta', 'Ready to Pre-Order?', 'พร้อมสั่งพรีออเดอร์แล้วหรือยัง?', 'Fresh, handcrafted baked goods made with the finest ingredients. Order today, pick up on your chosen day!', 'เบเกอรี่โฮมเมด อบสดใหม่เป็นรอบเล็ก ๆ ด้วยวัตถุดิบคุณภาพ สั่งวันนี้ รับในวันที่คุณเลือก', '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', NULL, NULL),
	('da292e69-020b-4371-9d23-935004c7072e', 'about_intro', 'Our Story', 'เรื่องราวของเรา', 'We are passionate about creating artisan baked goods with premium ingredients.', 'เรากำลังสร้างขนมปังช่างฝีมืออบสดใหม่ด้วยวัตถุดิบคุณภาพ', '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', NULL, NULL),
	('381b59f1-dd9f-4941-a0af-ed6aac86bdb6', 'how_it_works', 'How It Works', 'วิธีการสั่งซื้อ', 'Browse our products, add to your cart, and place your pre-order. Pick up on your preferred day.', 'ดูรายชื่อสินค้า เพิ่มลงตะกร้า และสั่งจองล่วงหน้า จากนั้นรับสินค้าในวันที่คุณต้องการ', '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', NULL, NULL);
