INSERT INTO "public"."cms_products" ("id", "slug", "category_id", "name_en", "name_th", "desc_en", "desc_th", "price", "image", "is_sold_out", "is_active", "sort_order", "stock_total", "stock_remaining", "created_at", "updated_at", "available_days", "stock_by_day", "name_zh", "desc_zh", "qr_code_url") VALUES
	('6fd852bc-9468-4bd2-a404-751130476d16', 'sourdough-loaf', '09733918-c224-40fc-9978-9bbd060f770c', 'Sourdough Loaf', 'ขนมปังฟืนสูร', 'Artisan sourdough with a tangy flavor and chewy crumb. Perfect for sandwiches or toasting.', 'ขนมปังฟืนสูรช่างฝีมือพร้อมรสชาติเปรี้ยวและเนื้อที่เหนียว สมบูรณ์แบบสำหรับแซนด์วิชหรือปิ้งขนมปัง', 65.00, NULL, false, true, 1, NULL, NULL, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '[]', '{}', '酸面包', '手工酸面包，口感微酸，内芯有嚼劲，最适合做三明治或烤面包片。', NULL),
	('618585c0-a3e2-4cac-acca-72cd0b09c34e', 'chocolate-cake', 'f424b263-5e52-4c87-bac0-c6f32e91e773', 'Chocolate Cake', 'เค้กช็อกโกแลต', 'Rich, moist chocolate cake with a silky chocolate ganache. A chocolate lover''s dream.', 'เค้กช็อกโกแลตเนื้ออ่อนอุดมสมบูรณ์พร้อมกาแนชช็อกโกแลตเรียบเนียน ฝันของคนรักช็อกโกแลต', 120.00, NULL, false, true, 1, NULL, NULL, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '[]', '{}', '巧克力蛋糕', '浓郁湿润的巧克力蛋糕，配上丝滑巧克力甘纳许，巧克力爱好者的梦想。', NULL),
	('817857f0-2052-49e1-905b-3232df2a18ea', 'mushroom-pizza', 'd5312ef4-391e-406f-a94e-c46d9b85221d', 'Mushroom Pizza', 'พิซซ่าเห็ด', 'Artisan pizza with fresh mushrooms, cheese, and herbs. A vegetarian favorite.', 'พิซซ่าช่างฝีมืออาหารมัดมะกรูด สด ชีส และสมุนไพร ตัวเลือกโปรดสำหรับผักเจ', 110.00, NULL, false, true, 2, NULL, NULL, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '[]', '{}', '蘑菇披萨', '手工披萨，配新鲜蘑菇、芝士和香草，素食者的最爱。', NULL),
	('2041166b-4f81-49a7-ada7-4095822f9611', 'strawberry-shortcake', 'f424b263-5e52-4c87-bac0-c6f32e91e773', 'Strawberry Shortcake', 'เค้กสตรอเบอร์รี่', 'Light sponge cake layered with fresh strawberries and whipped cream.', 'เค้กฟองน้ำเบาเรียงซ้อนกับสตรอเบอร์รี่สดและครีมเบา', 110.00, NULL, false, true, 2, NULL, NULL, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '[]', '{}', '草莓奶油蛋糕', '轻盈的海绵蛋糕，夹层为新鲜草莓和鲜奶油。', NULL),
	('ef6852a4-3ac4-4a0a-875d-6cb6427de9cc', 'spinach-quiche', 'd5312ef4-391e-406f-a94e-c46d9b85221d', 'Spinach & Cheese Quiche', 'แพยผักโขมและชีส', 'Savory quiche filled with fresh spinach, cheese, and cream. Perfect for brunch.', 'แพยคร่อมเต็มไปด้วยผักโขมสด ชีส และครีม สมบูรณ์แบบสำหรับอาหารเช้า', 95.00, NULL, false, true, 1, 10, 10, '2026-01-27 02:59:30.575688+00', '2026-08-22 22:42:54.097832+00', '["Sunday – In-Town", "Saturday – Mae Rim"]', '{"sunday_intown": 3, "saturday_maerim": 4, "Sunday – In-Town": 8, "Saturday – Mae Rim": 5}', '菠菜芝士法式咸派', '咸香法式咸派，内馅新鲜菠菜、芝士和奶油，早午餐的完美选择。', NULL),
	('c18bf138-2319-4458-8f71-f0f232230270', 'chocolate-croissant', '2693934a-86dd-45df-8b2a-ca3bbfbb6152', 'Chocolate Croissant', 'ครัวซองช็อกโกแลต', 'Buttery croissant filled with rich dark chocolate. Perfect for breakfast or any time of day.', 'ครัวซองเนยกรอบกรอบเต็มไปด้วยช็อกโกแลตดำเข้มข้น สมบูรณ์แบบสำหรับอาหารเช้าหรือเวลาใด ๆ', 50.00, NULL, false, true, 1, 10, 10, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '["Friday – Mae Rim", "Sunday – In-Town"]', '{"Sunday – In-Town": 0}', '巧克力可颂', '黄油可颂内馅浓郁黑巧克力，早餐或任何时候的完美选择。', NULL),
	('3358e1c9-d30c-41a2-bda5-0db4e17a598e', 'plain-croissant', '2693934a-86dd-45df-8b2a-ca3bbfbb6152', 'Plain Croissant', 'ครัวซองธรรมชาติ', 'Classic all-butter croissant with delicate, flaky layers. A timeless favorite.', 'ครัวซองเนยแบบคลาสสิกพร้อมชั้นกรอบเนียบ ตัวเลือกโปรดแบบนิรันดร์', 40.00, NULL, false, true, 2, NULL, NULL, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '[]', '{}', '原味可颂', '经典全黄油可颂，层次分明，酥脆轻盈，经典中的经典。', NULL),
	('b7f21ba5-497b-4065-9590-3c2bc2aa88f9', 'multigrain-bread', '09733918-c224-40fc-9978-9bbd060f770c', 'Multigrain Bread', 'ขนมปังธัญพืชหลายชนิด', 'Hearty multigrain loaf loaded with seeds and whole grains. Nutritious and delicious.', 'ขนมปังธัญพืชหลายชนิดเต็มไปด้วยเมล็ดและธัญพืชทั้งหมด มีประโยชน์และอร่อยเลิศ', 58.00, NULL, false, true, 2, NULL, NULL, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '[]', '{}', '杂粮面包', '饱满的多谷物面包，富含各种种子和全谷物，营养又美味。', NULL),
	('96f3291f-87b7-4519-a810-09d3575c82ec', 'almond-croissant', '2693934a-86dd-45df-8b2a-ca3bbfbb6152', 'Almond Croissant', 'ครัวซองอัลมอนด์', 'Topped with sliced almonds and a hint of almond cream. A nutty delight.', 'ตกแต่งด้วยอัลมอนด์สไลซ์และครีมอัลมอนด์เบาๆ ความสุขของถั่ว', 48.00, NULL, false, true, 3, NULL, NULL, '2026-01-27 02:59:30.575688+00', '2026-01-27 02:59:30.575688+00', '[]', '{}', '杏仁可颂', '表面撒有杏仁片和淡淡杏仁奶油，坚果香浓郁。', NULL);
